package vn.edu.hcmute.example3; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class AuthController {private final AuthService auth; AuthController(AuthService a){auth=a;} @GetMapping("/login") String login(){return "login";} @GetMapping("/register") String register(){return "register";} @PostMapping("/register") String registerSubmit(@RequestParam String username,@RequestParam String email,@RequestParam String fullName,@RequestParam String password,RedirectAttributes ra){try{auth.register(username,email,fullName,password);ra.addFlashAttribute("message","Đã tạo tài khoản. Hãy nhập mã xác nhận được gửi cho bạn.");return "redirect:/verify?email="+email;}catch(IllegalArgumentException e){ra.addFlashAttribute("error",e.getMessage());return "redirect:/register";}} @GetMapping("/verify") String verify(@RequestParam(required=false)String email,Model m){m.addAttribute("email",email);return "verify";} @PostMapping("/verify") String verifyPost(@RequestParam String email,@RequestParam String code,RedirectAttributes ra){if(auth.verify(email,"ACTIVATE",code)){ra.addFlashAttribute("message","Xác nhận tài khoản thành công.");return "redirect:/login";}ra.addFlashAttribute("error","Mã xác nhận không đúng hoặc đã hết hạn.");return "redirect:/verify?email="+email;} @GetMapping("/forgot-password") String forgot(){return "forgot";} @PostMapping("/forgot-password") String forgotPost(@RequestParam String email,RedirectAttributes ra){auth.issue(email,"RESET");ra.addFlashAttribute("message","Nếu email hợp lệ, mã xác nhận đã được gửi.");return "redirect:/reset-password?email="+email;} @GetMapping("/reset-password") String reset(@RequestParam(required=false)String email,Model m){m.addAttribute("email",email);return "reset";} @PostMapping("/reset-password") String resetPost(@RequestParam String email,@RequestParam String code,@RequestParam String password,RedirectAttributes ra){try{auth.reset(email,code,password);ra.addFlashAttribute("message","Đổi mật khẩu thành công.");return "redirect:/login";}catch(IllegalArgumentException e){ra.addFlashAttribute("error",e.getMessage());return "redirect:/reset-password?email="+email;}}}
